    alias perUnitOf: GetPerUnitOfForEquityDerivativeBase(fpmlBrokerEquityOption)

    set payout:
        Payout {
            OptionPayout:
                OptionPayout {
                    payerReceiver: MapSellerAsPayerAndBuyerAsReceiver(
